    e3_mb_init(mbDW, 1); e3_mb_init(mbW1, 1); e3_mb_init(mbW2, 1);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
    e3_mb_expect(mbDW, (unsigned)(C * 49 * 4));
    e3_mb_expect(mbW1, (unsigned)(BN * C * 4));
  }
  for (int i = tid; i < BN; i += E3_NT) sq[i] = 0.f;
  for (int i = tid; i < C4; i += E3_NT) gsum[i] = 0.f;
  __syncthreads();
  // ---- all weight loads issued at entry: dw weights and the W1 slice (fp32, resident)
  if (tid == 0) e3_bulk(e3_sa(DW), p.dww, (unsigned)(C * 49 * 4), mbDW);
  for (int n = tid; n < BN; n += E3_NT)
    e3_bulk(e3_sa(Wb + (size_t)n * LDW1), p.w1 + (size_t)(hb * BN + n) * C, (unsigned)(C * 4), mbW1);
