  if (hb == 0) {
    const size_t base = (size_t)b * C * HW + p0;
    const int tot = C * Tv;
    for (int i0 = tid; i0 < tot; i0 += E3_NT * 8) {
      float v[8]; size_t o[8];
#pragma unroll
      for (int u = 0; u < 8; u++) {
        const int i = i0 + u * E3_NT;
        v[u] = 0.f; o[u] = 0;
        if (i < tot) {
          const int c = i / Tv, j = i - c * Tv;
          o[u] = base + (size_t)c * HW + j;
          v[u] = __ldg(p.x + o[u]) + __ldg(p.b2 + c);
        }
