        float acc[4] = {bias, bias, bias, bias};
#pragma unroll
        for (int i = 0; i < 7; i++) {
          const int hh = h - 3 + i;
          const bool rowok = hh >= 0 && hh < H;
          float4 L = make_float4(0.f, 0.f, 0.f, 0.f), Cq = L, R = L;
          if (rowok) {
