os.makedirs('/tmp/e3p', exist_ok=True)
libs={}
import concurrent.futures as cf
def build(tag, defs):
    open(f'/tmp/e3p/{tag}.cu','w').write(SRC)
    r=subprocess.run(['nvcc','-O3','--use_fast_math','-std=c++17','-shared','-Xcompiler','-fPIC','-gencode','arch=compute_100a,code=sm_100a',*defs,'-o',f'/tmp/e3p/{tag}.so',f'/tmp/e3p/{tag}.cu'],capture_output=True,text=True)
    if r.returncode: print(r.stderr[-2000:])
    return tag
variants={'full':[], 'noconv':['-DNOCONV'], 'nopre':['-DNOPREFILL']}
with cf.ThreadPoolExecutor(3) as ex: list(ex.map(lambda kv: build(kv[0],kv[1]), variants.items()))
for k in variants: libs[k]=ctypes.CDLL(f'/tmp/e3p/{k}.so')
def mk(B,C,H,W):
    d='cuda'
    x=torch.randn(B,C,H,W,device=d); dww=torch.randn(C,1,7,7,device=d)/7**.5; dwb=torch.randn(C,device=d)
    lnw=torch.ones(C,device=d); lnb=torch.zeros(C,device=d); w1=torch.randn(4*C,C,device=d)/C**.5; b1=torch.randn(4*C,device=d)
    gw=torch.randn(1,1,1,4*C,device=d)/(4*C)**.5; gb=torch.randn(4*C,device=d); w2=torch.randn(C,4*C,device=d)/(4*C)**.5; b2=torch.randn(C,device=d)
    return [x,dww,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2]
for (B,C,H,W,NH,CH) in [(1,192,28,28,6,48),(1,192,28,28,4,16),(1,96,56,56,2,48),(1,96,56,56,1,32),(2,96,56,56,2,48),(4,192,28,28,6,16)]:
    ins=mk(B,C,H,W); out=torch.zeros(B,C,H,W,device='cuda'); ws=torch.empty(148*4*C,device='cuda'); tl=torch.zeros(148*8,dtype=torch.int64,device='cuda')
    info=(ctypes.c_int*6)()
    res={}
    for k,lib in libs.items():
        def fn(*a, lib=lib, tlp=0):
            ptrs=(ctypes.c_void_p*11)(*[t.data_ptr() for t in a[:11]])
            rc=lib.e3_launch_cfg(ptrs, ctypes.c_void_p(a[11].data_ptr()), ctypes.c_void_p(ws.data_ptr()), ctypes.c_void_p(tlp), B,C,H,W,NH,CH, ctypes.c_void_p(torch.cuda.current_stream().cuda_stream), info)
            assert rc==0, (rc, list(info))
        try:
            res[k]=bp.harness_time(fn, ins, [out])
        except AssertionError as e:
            print('skip', B,C,H,W,NH,CH, e); break
    if not res: continue
    # timeline (full)
    bp.flush_l2()
    ptrs=(ctypes.c_void_p*11)(*[t.data_ptr() for t in ins])
    libs['full'].e3_launch_cfg(ptrs, ctypes.c_void_p(out.data_ptr()), ctypes.c_void_p(ws.data_ptr()), ctypes.c_void_p(tl.data_ptr()), B,C,H,W,NH,CH, ctypes.c_void_p(torch.cuda.current_stream().cuda_stream), info)
    torch.cuda.synchronize()
    g=info[5]; s=tl[:g*8].view(g,8).cpu().numpy().astype(np.float64); s=(s-s[:,0].min())/1000.0
    med=np.median(s[:,:7],axis=0); mx=s[:,:7].max(axis=0)
    print(f'{B},{C},{H},{W} NH{NH} T{info[0]} Tp{info[1]} CH{info[2]} ntt{info[3]} smem{info[4]} grid{g}: ' + ' '.join(f'{k}={v:.1f}' for k,v in res.items()))
    print('   stamps med', np.round(med,2), ' max', np.round(mx,2))

import re, subprocess
S=open('/tmp/e3p/full.cu').read()
old_mma = S[S.index('__device__ __forceinline__ void e3_mma_unit'):S.index('template <int MODE>')]
new_mma = r'''__device__ __forceinline__ void e3_mma_unit(const unsigned short* A, int lda, const float* Bm, int ldb, int K, float (&acc)[4][4], int g, int t) {
  const unsigned short* a0p = A + g * lda + 4 * t; const unsigned short* a1p = a0p + 8 * lda; const float* bp = Bm + g * ldb + 4 * t;
#pragma unroll 1
  for (int k0 = 0; k0 < K; k0 += 32) {
    uint2 a0[2], a1[2]; float4 w[2][4];
#pragma unroll
