S2 = S.replace(old_mma, new_mma)
S2 = S2.replace('for (int u = warp; u < units; u += E3_NW)', 'for (int u = __shfl_sync(0xffffffffu, warp, 0); u < units; u += E3_NW)')
open('/tmp/e3p/fix.cu','w').write(S2)
for f in ['full','fix']:
